// Normalise whatever arrives into a single case-file shape.
// Accepts: {case_file:{...}}, or {ev, metrics, rule_flags}, or nothing (-> dev fixture).
function caseFile(q) {
  const raw = (q && q.case_file) ? q.case_file : ((q && (q.ev || q.metrics || q.session)) ? q : null);
  if (!raw) return DEV_CASE_FILE;
  const ev = raw.ev || raw;
  return {
    prescription: raw.prescription || ev.prescription || DEV_CASE_FILE.prescription,
    metrics:      raw.metrics      || DEV_CASE_FILE.metrics,
    rule_flags:   raw.rule_flags   || [],
    session:      raw.session      || ev.session  || DEV_CASE_FILE.session,
    history:      raw.history      || ev.history  || DEV_CASE_FILE.history,
  };
}
const q = $input.first().json || {};
const cf = caseFile(q);
const code = String(q.fault_code || "").trim();
const perSession = (cf.history || []).map(h => ({
  session_id: h.session_id,
  date: h.date || null,
  count: (h.fault_counts && h.fault_counts[code]) || 0,
}));
const totalInHistory = perSession.reduce((a, b) => a + b.count, 0);
const currentCount = (cf.metrics && cf.metrics.fault_counts && cf.metrics.fault_counts[code]) || 0;
return [{ json: {
  fault_code: code,
  current_session_count: currentCount,
  history: perSession,
  total_in_history: totalInHistory,
  seen_in_history: totalInHistory > 0,
  is_new_this_session: currentCount > 0 && totalInHistory === 0,
} }];
